import React, { useState, useEffect } from 'react';
import MainNav from '../MainNav/MainNav';
import './Home.css';

function Home() {
  const [currentSlide, setCurrentSlide] = useState(0);
  
  const slides = [
    {
      image: "url('https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80')",
      title: "Discover Amazing Artists",
      description: "Find and manage your favorite artists in one place",
      buttonText: "Browse Artists"
    },
    {
      image: "url('https://images.unsplash.com/photo-1470225620780-dba8ba36b745?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80')",
      title: "Upcoming Events",
      description: "Never miss a concert or performance",
      buttonText: "View Events"
    },
    {
      image: "url('https://images.unsplash.com/photo-1501612780327-45045538702b?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80')",
      title: "Artist Management Made Easy",
      description: "Streamline your artist management workflow",
      buttonText: "Get Started"
    }
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev === slides.length - 1 ? 0 : prev + 1));
    }, 5000);
    return () => clearInterval(interval);
  }, [slides.length]);

  return (
    <div className="home-container">
      <MainNav />
      
      {/* Hero Slider */}
      <div className="slider-container">
        {slides.map((slide, index) => (
          <div 
            key={index}
            className={`slide ${index === currentSlide ? 'active' : ''}`}
            style={{ backgroundImage: slide.image }}
          >
            <div className="slide-content">
              <h2>{slide.title}</h2>
              <p>{slide.description}</p>
              <button className="slide-btn">{slide.buttonText}</button>
            </div>
          </div>
        ))}
        
        <div className="slider-dots">
          {slides.map((_, index) => (
            <div 
              key={index}
              className={`dot ${index === currentSlide ? 'active' : ''}`}
              onClick={() => setCurrentSlide(index)}
            />
          ))}
        </div>
      </div>
      
      {/* Featured Artists Section */}
      <div className="featured-artists">
        <h2 className="section-title">Featured Artists</h2>
        <div className="artist-grid">
          {/* You would map through your artists data here */}
          <div className="artist-card">
            <img src="https://via.placeholder.com/300" alt="Artist" className="artist-image" />
            <div className="artist-info">
              <h3 className="artist-name">Artist Name</h3>
              <p className="artist-genre">Genre</p>
            </div>
          </div>
          {/* Add more artist cards */}
        </div>
      </div>
      
      {/* Upcoming Events Section */}
      <div className="upcoming-events">
        <h2 className="section-title">Upcoming Events</h2>
        <div className="event-list">
          {/* You would map through your events data here */}
          <div className="event-item">
            <div className="event-date">
              <div className="event-day">15</div>
              <div className="event-month">Jun</div>
            </div>
            <div className="event-details">
              <h3 className="event-title">Summer Music Festival</h3>
              <p className="event-location">Central Park, New York</p>
            </div>
          </div>
          {/* Add more event items */}
        </div>
      </div>
    </div>
  );
}

export default Home;
